def eval_rpn(tokens={{tokens}}):
    st = []
    ops = {'+': lambda a,b: a+b, '-': lambda a,b: a-b,
           '*': lambda a,b: a*b, '/': lambda a,b: a/b,
           '^': lambda a,b: a**b}
    for t in tokens:
        if t in ops:
            b = st.pop(); a = st.pop()
            st.append(ops[t](a, b))
        else:
            st.append(float(t))
    return st[0]
